<script setup>
import { ref,onMounted } from 'vue'; import { api } from '../services/api'
const albums=ref([]),categories=ref([]),settings=ref({}),error=ref('')
onMounted(async()=>{try {const [a,c,s]=await Promise.all([api.get('/albums'),api.get('/categories'),api.get('/settings')]); albums.value=a.data.data; categories.value=c.data; settings.value=s.data}catch{error.value='Galeri belum dapat dimuat. Pastikan server API berjalan.'}})
</script>
<template><main><section class="hero" :style="settings.hero_image ? {backgroundImage:`linear-gradient(90deg,rgba(0,0,0,.72),rgba(0,0,0,.15)),url(${settings.hero_image})`} : {}"><div class="hero-content"><div class="eyebrow light"><i></i> JAKARTA DALAM BINGKAI</div><h1>Merekam Cerita,<br><em>Mengabadikan</em><br>Jakarta<span>.</span></h1><p>Kumpulan dokumentasi visual tentang kehidupan, aktivitas, budaya, dan perkembangan Kota Jakarta.</p><router-link class="button" to="/albums">Jelajahi Gallery <span>↗</span></router-link></div><div class="hero-bottom"><span>01 / CERITA JAKARTA</span><span>SCROLL UNTUK MENJELAJAHI ↓</span></div></section><section class="intro wrap"><div><div class="eyebrow"><i></i> SEBUAH ARSIP VISUAL</div><h2>Setiap sudut punya cerita.<br><em>Setiap cerita berarti.</em></h2></div><p>Dari denyut keseharian hingga momen yang membentuk kota, kami mengabadikan Jakarta melalui lensa yang lebih dekat.</p></section><section class="wrap section"><div class="section-head"><div><div class="eyebrow"><i></i> PILIHAN EDITOR</div><h2>Cerita terbaru<span>.</span></h2></div><router-link class="text-link" to="/albums">Lihat semua album ↗</router-link></div><p v-if="error" class="notice">{{error}}</p><div v-else-if="!albums.length" class="notice">Belum ada album yang dipublikasikan.</div><div class="album-grid"><router-link v-for="a in albums.slice(0,6)" :key="a.id" :to="'/albums/'+a.slug" class="card"><div class="card-image"><img v-if="a.cover" :src="a.cover.thumbnail_url" loading="lazy" :alt="a.title"><span v-else class="placeholder">JAKARTA<br>PHOTO GALLERY</span><span class="card-tag">{{a.category?.name}}</span></div><div class="card-meta">{{a.event_date?.slice(0,10) || 'DOKUMENTASI'}} <span>{{a.photos_count}} FOTO</span></div><h3>{{a.title}} <span>↗</span></h3></router-link></div></section><section class="categories" id="kategori"><div class="wrap"><div class="section-head"><div><div class="eyebrow"><i></i> JELAJAHI JAKARTA</div><h2>Temukan cerita<br><em>yang ingin Anda lihat.</em></h2></div><p>Sembilan perspektif, satu Jakarta.<br>Jelajahi dokumentasi berdasarkan tema.</p></div><div class="category-list"><router-link v-for="(c,i) in categories" :key="c.id" :to="'/albums?category='+c.slug"><span class="cat-no">{{String(i+1).padStart(2,'0')}}</span><strong>{{c.name}}</strong><span>{{c.albums_count}} ALBUM</span><b>↗</b></router-link></div></div></section><section class="closing wrap"><div class="eyebrow"><i></i> JAKARTA, DALAM SETIAP MOMEN</div><h2>Kota terus bergerak.<br><em>Ceritanya terus hidup.</em></h2><router-link to="/albums" class="button dark">Jelajahi semua album ↗</router-link></section></main></template>
